package com.autoops.ai.provider;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.stereotype.Service;import org.springframework.web.client.RestClient;import java.util.*;@Service public class OpenRouterAIProvider implements AIProvider{private final RestClient client;private final String model;public OpenRouterAIProvider(@Value("${autoops.ai.base-url}")String url,@Value("${autoops.ai.api-key}")String key,@Value("${autoops.ai.model}")String model){this.client=RestClient.builder().baseUrl(url).defaultHeader(HttpHeaders.AUTHORIZATION,"Bearer "+key).build();this.model=model;}public AIResponse chat(List<Message> messages,List<Map<String,Object>> tools){Map<String,Object> body=new LinkedHashMap<>();body.put("model",model);body.put("messages",messages.stream().map(m->Map.of("role",m.role(),"content",m.content())).toList());if(tools!=null&&!tools.isEmpty())body.put("tools",tools);Map<?,?> r=client.post().uri("/chat/completions").contentType(MediaType.APPLICATION_JSON).body(body).retrieve().body(Map.class);if(r==null)return new AIResponse("",List.of());var choices=(List<?>)r.get("choices");if(choices==null||choices.isEmpty())return new AIResponse("",List.of());var msg=(Map<?,?>)((Map<?,?>)choices.get(0)).get("message");return new AIResponse(String.valueOf(msg.getOrDefault("content","")),List.of());}}
